"use strict";(globalThis.webpackChunkgrc||=[]).push([[98377],{26250(e){e.exports=JSON.parse('{"citeKey":"haider2018horizon","slug":"haider-2018-horizon-8cad","title":"Horizon: A Multi-abstraction Framework for Graph Analytics","authors":["A. Haider","F. Checconi","X. Que","L. Schneidenbach","D. Buono","X.-H. Sun"],"venue":"The ACM International Conference on Computing Frontiers 2018 (CF\'18), Italy, 2018. pp. 252-255","type":"Conference","entryType":"inproceedings","date":"May, 2018","year":2018,"era":"iit","month":5,"doi":"10.1145/3203217.3203270","abstract":"In this paper we present Horizon, a distributed graph processing framework achieving close to native performance without penal- izing productivity by providing a multi-layer, multi-abstraction model of computation. Compared to current frameworks, Horizon extends the scope of computation by exposing two notions usually relegated to implementations: graph data models and communica- tion models. Horizon can reduce execution time by an average of 5.3\xd7 across different applications and datasets and process an order of magnitude larger graphs when compared to the state of the art.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2018/haider-2018-horizon-8cad.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);